    const cur = document.getElementById('dish');
    const next = document.createElement(e.target.checked ? 's' : 'span');
    next.id = 'dish';
    next.append(...cur.childNodes);
    cur.replaceWith(next);
    document.getElementById('note').textContent = e.target.checked ? ' (품절)' : '';
