  const ranges = [];
  let at = node.data.indexOf('도롱뇽');
  while (at >= 0) {
    const r = new Range();
    r.setStart(node, at);
    r.setEnd(node, at + 3);
    ranges.push(r);
    at = node.data.indexOf('도롱뇽', at + 1);
  }
  if (window.CSS && CSS.highlights) CSS.highlights.set('hit', new Highlight(...ranges));
  console.log('칠한 범위 ' + ranges.length + '개');
