<script>
  document.addEventListener('click', (e) => {
    const lang = e.target.dataset.lang;
    if (!lang) return;
    const fmt = new Intl.DateTimeFormat(lang, { dateStyle: 'long', timeZone: 'Asia/Seoul' });
    const rel = new Intl.RelativeTimeFormat(lang, { numeric: 'auto' });
    for (const t of document.querySelectorAll('time')) {
      const days = Math.round((new Date(t.dateTime) - Date.now()) / 86400000);
      t.textContent = fmt.format(new Date(t.dateTime)) + ' (' + rel.format(days, 'day') + ')';
    }
    console.log(lang, document.querySelector('time').textContent);
  });
