function pairs(ruby: Element): [string, string][] {
  const out: [string, string][] = [];
  let base = "";
  for (const node of ruby.childNodes) {
    const tag = node instanceof Element ? node.localName : "";
    if (tag === "rt") {
      out.push([base.trim(), node.textContent ?? ""]);
      base = "";
    } else if (tag !== "rp") {
      base += node.textContent ?? "";
    }
  }
  return out;
}
