          html: `<canvas id="c" width="240" height="70" style="outline: 1px dashed #999">
  <button type="button" id="b1">1월 매출 막대</button>
  <button type="button" id="b2">2월 매출 막대</button>
</canvas>
<script>
  const ctx = c.getContext('2d');
  const bars = [[b1, 20, 30], [b2, 120, 50]];
  function paint() {
    ctx.clearRect(0, 0, c.width, c.height);
    for (const [el, x, h] of bars) {
      ctx.fillStyle = '#2f6f9f';
      ctx.fillRect(x, 65 - h, 60, h);
      ctx.beginPath();
      ctx.rect(x - 4, 61 - h, 68, h + 8);
      ctx.drawFocusIfNeeded(el);
    }
  }
  for (const [el] of bars) { el.addEventListener('focus', paint); el.addEventListener('blur', paint); }
  paint();
</script>`,
