select.remove(1);                            // 두 번째 보기 빼기

select.value = "parrot";                     // 고르기. change는 나지 않는다
select.dispatchEvent(new Event("change", { bubbles: true })); // 필요하면 직접

const all = [...select.selectedOptions].map((o) => o.value); // multiple일 때`,
