const c = new Option("우유", "milk", true);   // selected 속성이 붙는다
const d = new Option("두유", "soy", false, true); // 지금 골라짐, 속성은 없음

select.add(a);
select.add(d);            // d가 골라진다
console.log(select.value); // "soy"`,
